//! Native Vulkan compute execution of upstream's WGSL synthesis kernel.
//! wgpu owns feature negotiation and Vulkan synchronization (no render surface).
use std::{borrow::Cow, collections::BTreeMap, sync::{Arc, Mutex, mpsc, atomic::{AtomicU8, Ordering}}, time::Duration};
use svpflow_core::smooth_engine::{GpuJob, GpuParams};

// Only accept data generated by wgpu in this process or in the app's
// private, UID-checked Android cache directory (not imported files).
use crate::pipeline_cache;
const MAX_PIPELINE_CACHE_BYTES: usize = pipeline_cache::MAX_BYTES;
static WARM_PIPELINE_CACHE: Mutex<Option<(String, Vec<u8>)>> = Mutex::new(None);

fn warm_cache_data(key: &str) -> Option<Vec<u8>> {
    let memory = WARM_PIPELINE_CACHE.lock().ok()
        .and_then(|cache| cache.as_ref().filter(|(k, _)| k == key).map(|(_, data)| data.clone()));
    memory.or_else(|| pipeline_cache::load(key))
}

fn remember_cache_data(key: &str, cache: &wgpu::PipelineCache) -> bool {
    if let Some(data) = cache.get_data().filter(|v| v.len() <= MAX_PIPELINE_CACHE_BYTES) {
        if let Ok(mut warm) = WARM_PIPELINE_CACHE.lock() {
            *warm = Some((key.to_owned(), data));
            return true;
        }
    }
    false
}

struct PlaneBinding {
    textures: [wgpu::Texture; 5],
    group: wgpu::BindGroup,
}

struct Source {
    packed: wgpu::Texture,
    linear: Option<wgpu::Texture>,
    linear_valid: bool,
}
struct FieldCache {
    texture: wgpu::Texture,
    grid: (u32, u32),
    values: Vec<u16>,
}
struct MaskCache {
    texture: wgpu::Texture,
    grid: (u32, u32),
    values: Option<Vec<u8>>,
}

// The previous render has completed before the next render starts. Request
// remapping after submission and service callbacks during the readback wait.
const MAX_UPLOAD_SLOTS: usize = 8;
const MAX_UPLOAD_BYTES: u64 = 48 * 1024 * 1024;
struct UploadSlot {
    buffer: wgpu::Buffer,
    status: Arc<AtomicU8>, // 0 pending, 1 mapped, 2 failed
}
#[derive(Default)]
struct UploadPool {
    slots: Vec<UploadSlot>,
    submitted: Vec<wgpu::Buffer>,
}

struct PendingReadback {
    buffer: wgpu::Buffer,
    result: mpsc::Receiver<Result<(), wgpu::BufferAsyncError>>,
    deadline: std::time::Instant,
}

pub struct Gpu {
    device: wgpu::Device,
    queue: wgpu::Queue,
    shader: wgpu::ShaderModule,
    layout: wgpu::BindGroupLayout,
    pipeline_layout: wgpu::PipelineLayout,
    prepass: wgpu::ComputePipeline,
    prepass_layout: wgpu::BindGroupLayout,
    pipelines: BTreeMap<[i32; 6], wgpu::ComputePipeline>,
    driver_cache: Option<(String, wgpu::PipelineCache)>,
    cache_dirty: bool,
    cache_updated: bool,
    #[cfg(test)]
    pub(super) force_clear_output: bool,
    compact_fields: bool,
    sources: BTreeMap<i32, Source>,
    recycled_sources: Vec<Source>,
    empty_prepass: wgpu::BindGroup,
    base_field: Option<FieldCache>,
    ext_field: Option<FieldCache>,
    mask: Option<MaskCache>,
    uniforms: [wgpu::Buffer; 3],
    plane_bindings: [Option<PlaneBinding>; 3],
    uploads: Mutex<UploadPool>,
    output: wgpu::Buffer,
    readback: wgpu::Buffer,
    readback_next: Option<wgpu::Buffer>,
    pending_next: Option<PendingReadback>,
    width: u32,
    height: u32,
    bytes: u64,
}

impl Gpu {
    #[cfg(test)]
    pub(super) fn uses_compact_fields(&self) -> bool { self.compact_fields }

    pub fn clear_sources(&mut self) {
        self.cancel_prefetch();
        self.recycled_sources.extend(std::mem::take(&mut self.sources).into_values());
        self.recycled_sources.truncate(2);
        self.plane_bindings = std::array::from_fn(|_| None);
    }
    pub fn new(width: u32, height: u32) -> Result<Self, String> {
        Self::new_with_compact_fields(width, height, true)
            .or_else(|_| Self::new_with_compact_fields(width, height, false))
    }

    pub(super) fn new_with_compact_fields(width: u32, height: u32, allow_compact: bool) -> Result<Self, String> {
        let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor {
            backends: wgpu::Backends::VULKAN,
            ..Default::default()
        });
        let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            force_fallback_adapter: false,
            compatible_surface: None,
        }))
        .ok_or("no Vulkan compute adapter")?;
        let info = adapter.get_info();
        // A software adapter is permitted exclusively in the test build
        // for deterministic correctness CI, never in the Android library.
        #[cfg(test)]
        let software_test = std::env::var("AMBIENTSVP_TEST_SOFTWARE_VULKAN").as_deref() == Ok("1");
        #[cfg(not(test))]
        let software_test = false;
        if info.device_type == wgpu::DeviceType::Cpu && !software_test {
            return Err("software Vulkan adapter".into());
        }
        let cache_key = wgpu::util::pipeline_cache_key(&info)
            .filter(|_| adapter.features().contains(wgpu::Features::PIPELINE_CACHE))
            .map(|key| format!("{key}:{}:{}:{}", info.name, info.driver, info.driver_info));
        let cache_feature = if cache_key.is_some() {
            wgpu::Features::PIPELINE_CACHE
        } else {
            wgpu::Features::empty()
        };
        // UNORM16 encodes every upstream u16 exactly after the shader's
        // round(x * 65535). Preserve RGBA32Float on adapters without support.
        let compact_fields = allow_compact
            && adapter.features().contains(wgpu::Features::TEXTURE_FORMAT_16BIT_NORM)
            && adapter.get_texture_format_features(wgpu::TextureFormat::Rgba16Unorm)
                .allowed_usages.contains(wgpu::TextureUsages::TEXTURE_BINDING
                    | wgpu::TextureUsages::COPY_DST | wgpu::TextureUsages::COPY_SRC)
            && synthesis_source(true).is_ok();
        let features = cache_feature | if compact_fields {
            wgpu::Features::TEXTURE_FORMAT_16BIT_NORM
        } else { wgpu::Features::empty() };
        let (device, queue) = pollster::block_on(adapter.request_device(
            &wgpu::DeviceDescriptor {
                label: Some("Open-SVPFlow compute"),
                required_features: features,
                required_limits: wgpu::Limits::default().using_resolution(adapter.limits()),
                memory_hints: wgpu::MemoryHints::MemoryUsage,
            },
            None,
        ))
        .map_err(|e| e.to_string())?;
        device.push_error_scope(wgpu::ErrorFilter::Validation);
        let driver_cache = cache_key.map(|key| {
            let data = warm_cache_data(&key);
            // SAFETY: data is produced by get_data, from our own process or
            // an earlier instance of this app in its private cache. The
            // adapter/driver key and checksum are checked; arbitrary imported
            // data is never accepted. This trusts the Android UID sandbox.
            // wgpu additionally validates its own cache format/adapter key.
            let cache = unsafe { device.create_pipeline_cache(&wgpu::PipelineCacheDescriptor {
                label: Some("SVP warm compute cache"),
                data: data.as_deref(),
                fallback: true,
            }) };
            (key, cache)
        });
        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("Open-SVPFlow smooth.wgsl"),
            source: wgpu::ShaderSource::Wgsl(synthesis_source(compact_fields)?),
        });
        let mut entries = vec![wgpu::BindGroupLayoutEntry {
            binding: 0,
            visibility: wgpu::ShaderStages::COMPUTE,
            ty: wgpu::BindingType::Buffer {
                ty: wgpu::BufferBindingType::Uniform,
                has_dynamic_offset: false,
                min_binding_size: None,
            },
            count: None,
        }];
        for binding in 1..=5 {
            entries.push(texture_entry(binding));
        }
        entries.push(wgpu::BindGroupLayoutEntry {
            binding: 6,
            visibility: wgpu::ShaderStages::COMPUTE,
            ty: wgpu::BindingType::Buffer {
                ty: wgpu::BufferBindingType::Storage { read_only: false },
                has_dynamic_offset: false,
                min_binding_size: None,
            },
            count: None,
        });
        let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: None,
            entries: &entries,
        });
        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: None,
            bind_group_layouts: &[&layout],
            push_constant_ranges: &[],
        });
        let prepass_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: None,
            entries: &[
                texture_entry(0),
                wgpu::BindGroupLayoutEntry {
                    binding: 1,
                    visibility: wgpu::ShaderStages::COMPUTE,
                    ty: wgpu::BindingType::StorageTexture {
                        access: wgpu::StorageTextureAccess::WriteOnly,
                        format: wgpu::TextureFormat::R32Float,
                        view_dimension: wgpu::TextureViewDimension::D2,
                    },
                    count: None,
                },
            ],
        });
        let empty = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: None,
            entries: &[],
        });
        let pre_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: None,
            bind_group_layouts: &[&empty, &prepass_layout],
            push_constant_ranges: &[],
        });
        let empty_prepass = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None, layout: &empty, entries: &[],
        });
        let prepass = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: None,
            layout: Some(&pre_layout),
            module: &shader,
            entry_point: Some("linear_luma"),
            compilation_options: Default::default(),
            cache: driver_cache.as_ref().map(|(_, cache)| cache),
        });
        let bytes = (width as u64 * height as u64 * 3 / 2).div_ceil(4) * 4;
        let output = device.create_buffer(&wgpu::BufferDescriptor {
            label: None,
            size: bytes,
            usage: wgpu::BufferUsages::STORAGE
                | wgpu::BufferUsages::COPY_SRC
                | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        let readback = device.create_buffer(&wgpu::BufferDescriptor {
            label: None,
            size: bytes,
            usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        if let Some(e) = pollster::block_on(device.pop_error_scope()) {
            return Err(e.to_string());
        }
        let uniforms = std::array::from_fn(|_| device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("SVP plane parameters"),
            size: 96,
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        }));
        Ok(Self {
            device,
            queue,
            shader,
            layout,
            pipeline_layout,
            prepass,
            prepass_layout,
            pipelines: BTreeMap::new(),
            driver_cache,
            cache_dirty: true,
            cache_updated: false,
            #[cfg(test)]
            force_clear_output: false,
            compact_fields,
            sources: BTreeMap::new(),
            recycled_sources: Vec::new(),
            empty_prepass,
            base_field: None,
            ext_field: None,
            mask: None,
            uniforms,
            plane_bindings: std::array::from_fn(|_| None),
            uploads: Mutex::new(UploadPool::default()),
            output,
            readback,
            readback_next: None,
            pending_next: None,
            width,
            height,
            bytes,
        })
    }

    fn texture(
        &self,
        width: u32,
        height: u32,
        format: wgpu::TextureFormat,
        storage: bool,
    ) -> wgpu::Texture {
        self.device.create_texture(&wgpu::TextureDescriptor {
            label: None,
            size: wgpu::Extent3d {
                width,
                height,
                depth_or_array_layers: 1,
            },
            mip_level_count: 1,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format,
            view_formats: &[],
            usage: wgpu::TextureUsages::TEXTURE_BINDING
                | if cfg!(test) { wgpu::TextureUsages::COPY_SRC } else { wgpu::TextureUsages::empty() }
                | wgpu::TextureUsages::COPY_DST
                | if storage {
                    wgpu::TextureUsages::STORAGE_BINDING
                } else {
                    wgpu::TextureUsages::empty()
                },
        })
    }

    // Keep the explicit MAP_WRITE allocation: Queue::write_texture and implicit
    // transient staging have crashed Android gfxstream at video resolutions.
    // Fill the mapped allocation directly, with no intermediate padded Vec.
    fn upload_rows(
        &self,
        encoder: &mut wgpu::CommandEncoder,
        texture: &wgpu::Texture,
        w: u32,
        h: u32,
        stride: u32,
        mut fill: impl FnMut(usize, &mut [u8]),
    ) {
        let pitch = stride.div_ceil(wgpu::COPY_BYTES_PER_ROW_ALIGNMENT)
            * wgpu::COPY_BYTES_PER_ROW_ALIGNMENT;
        let size = u64::from(pitch) * u64::from(h);
        let staging = {
            let mut pool = self.uploads.lock().unwrap();
            pool.slots.retain(|slot| slot.status.load(Ordering::Acquire) != 2);
            let reuse = pool.slots.iter().position(|slot|
                slot.buffer.size() == size && slot.status.load(Ordering::Acquire) == 1);
            reuse.map(|i| pool.slots.swap_remove(i).buffer)
        }.unwrap_or_else(|| self.device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("SVP explicit texture upload"),
            size,
            usage: wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::MAP_WRITE,
            mapped_at_creation: true,
        }));
        {
            let mut mapped = staging.slice(..).get_mapped_range_mut();
            for (row, dst) in mapped.chunks_exact_mut(pitch as usize).enumerate() {
                fill(row, &mut dst[..stride as usize]);
            }
        }
        staging.unmap();
        encoder.copy_buffer_to_texture(
            wgpu::TexelCopyBufferInfo {
                buffer: &staging,
                layout: wgpu::TexelCopyBufferLayout {
                    offset: 0, bytes_per_row: Some(pitch), rows_per_image: Some(h),
                },
            },
            texture.as_image_copy(),
            wgpu::Extent3d { width: w, height: h, depth_or_array_layers: 1 },
        );
        self.uploads.lock().unwrap().submitted.push(staging);
    }

    fn recycle_uploads(&self) {
        let mut pool = self.uploads.lock().unwrap();
        let submitted = std::mem::take(&mut pool.submitted);
        let mut bytes: u64 = pool.slots.iter().map(|s| s.buffer.size()).sum();
        for buffer in submitted {
            if pool.slots.len() >= MAX_UPLOAD_SLOTS || bytes + buffer.size() > MAX_UPLOAD_BYTES {
                continue;
            }
            let status = Arc::new(AtomicU8::new(0));
            let callback_status = Arc::clone(&status);
            buffer.slice(..).map_async(wgpu::MapMode::Write, move |result| {
                callback_status.store(if result.is_ok() { 1 } else { 2 }, Ordering::Release);
            });
            bytes += buffer.size();
            pool.slots.push(UploadSlot { buffer, status });
        }
    }

    /// Stage a newly decoded HD source while the CPU constructs its super
    /// frame and motion vectors. Queue ordering makes the texture ready for
    /// any later synthesis without waiting on the CPU. Do not speculatively
    /// allocate an unbounded queue or add submissions for small frames.
    pub fn stage_source(&mut self, n: i32, data: &[u8]) -> Result<(), String> {
        let pixels = u64::from(self.width) * u64::from(self.height);
        if pixels < 1280 * 720 || pixels > 1920 * 1080
            || self.sources.len() >= 3 || self.sources.contains_key(&n) {
            return Ok(());
        }
        self.device.poll(wgpu::Maintain::Poll);
        self.device.push_error_scope(wgpu::ErrorFilter::Validation);
        let mut encoder = self.device.create_command_encoder(&Default::default());
        self.source(n, data, false, &mut encoder);
        self.queue.submit([encoder.finish()]);
        self.recycle_uploads();
        if let Some(error) = pollster::block_on(self.device.pop_error_scope()) {
            return Err(error.to_string());
        }
        Ok(())
    }

    // A failed input must not leave the same frame index cached with pixels
    // from a rejected push. A subsequent retry may supply a different image.
    pub fn discard_source(&mut self, n: i32) {
        if let Some(source) = self.sources.remove(&n) {
            if self.recycled_sources.len() < 2 { self.recycled_sources.push(source); }
        }
        self.plane_bindings = std::array::from_fn(|_| None);
    }

    fn source(&mut self, n: i32, data: &[u8], linear_needed: bool,
              encoder: &mut wgpu::CommandEncoder) {
        let (w, h) = (self.width, self.height);
        if !self.sources.contains_key(&n) {
            let mut source = self.recycled_sources.pop().unwrap_or_else(|| Source {
                packed: self.texture(w, h * 3 / 2, wgpu::TextureFormat::R8Unorm, false),
                linear: None,
                linear_valid: false,
            });
            source.linear_valid = false;
            let (width, height) = (w as usize, h as usize);
            let luma = width * height;
            let half = width / 2;
            self.upload_rows(encoder, &source.packed, w, h * 3 / 2, w, |row, dst| {
                if row < height {
                    dst.copy_from_slice(&data[row * width..(row + 1) * width]);
                } else {
                    let offset = (row - height) * half;
                    dst[..half].copy_from_slice(&data[luma + offset..luma + offset + half]);
                    let v = luma * 5 / 4 + offset;
                    dst[half..].copy_from_slice(&data[v..v + half]);
                }
            });
            self.sources.insert(n, source);
        }
        if !linear_needed || self.sources[&n].linear_valid {
            return;
        }
        if self.sources[&n].linear.is_none() {
            let texture = self.texture(w, h, wgpu::TextureFormat::R32Float, true);
            self.sources.get_mut(&n).unwrap().linear = Some(texture);
        }
        let source = self.sources.get_mut(&n).unwrap();
        let input_view = source.packed.create_view(&Default::default());
        let output_view = source.linear.as_ref().unwrap().create_view(&Default::default());
        let group = self.device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &self.prepass_layout,
            entries: &[texture_binding(0, &input_view), texture_binding(1, &output_view)],
        });
        {
            let mut pass = encoder.begin_compute_pass(&Default::default());
            pass.set_pipeline(&self.prepass);
            pass.set_bind_group(0, &self.empty_prepass, &[]);
            pass.set_bind_group(1, &group, &[]);
            pass.dispatch_workgroups(w.div_ceil(16), h.div_ceil(16), 1);
        }
        source.linear_valid = true;
    }

    fn field(&self, encoder: &mut wgpu::CommandEncoder, cache: &mut Option<FieldCache>,
             data: &[u16], w: u32, h: u32) {
        if cache.as_ref().is_some_and(|c| c.grid == (w, h) && c.values.as_slice() == data) {
            return;
        }
        let mut field = cache.take().filter(|c| c.grid == (w, h)).unwrap_or_else(|| FieldCache {
            texture: self.texture(w, h, if self.compact_fields {
                wgpu::TextureFormat::Rgba16Unorm
            } else { wgpu::TextureFormat::Rgba32Float }, false),
            grid: (w, h),
            values: Vec::new(),
        });
        let row_values = w as usize * 4;
        if self.compact_fields {
            self.upload_rows(encoder, &field.texture, w, h, w * 8, |row, dst| {
                for (out, value) in dst.chunks_exact_mut(2)
                    .zip(&data[row * row_values..(row + 1) * row_values]) {
                    out.copy_from_slice(&value.to_le_bytes());
                }
            });
        } else {
            self.upload_rows(encoder, &field.texture, w, h, w * 16, |row, dst| {
                for (out, value) in dst.chunks_exact_mut(4)
                    .zip(&data[row * row_values..(row + 1) * row_values]) {
                    out.copy_from_slice(&(*value as f32).to_le_bytes());
                }
            });
        }
        field.values.clear();
        field.values.extend_from_slice(data);
        *cache = Some(field);
    }

    pub fn render(
        &mut self,
        job: &GpuJob,
        current: &[u8],
        next: &[u8],
        output: impl FnOnce(&[u8]),
    ) -> Result<(), String> {
        self.cancel_prefetch();
        let pending = self.submit(job, current, next, self.readback.clone())?;
        self.finish(pending, output)
    }

    /// Two outputs from the same source pair, ordered on one Vulkan queue.
    /// The second command reuses source/field/output resources only after the
    /// first copy-to-readback command; it has its own readback allocation.
    /// Both jobs are submitted before waiting for either mapped result.
    /// The second mapping is consumed directly by the next receive call;
    /// never stage its pixels in an extra CPU frame allocation.
    pub fn render_pair(
        &mut self,
        first: &GpuJob,
        second: &GpuJob,
        current: &[u8],
        next: &[u8],
        output: impl FnOnce(&[u8]),
    ) -> Result<(), String> {
        if first.n != second.n { return Err("different source pairs".into()); }
        self.cancel_prefetch();
        let second_buffer = self.readback_next.get_or_insert_with(|| self.device.create_buffer(
            &wgpu::BufferDescriptor {
                label: Some("SVP second in-flight readback"),
                size: self.bytes,
                usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
                mapped_at_creation: false,
            })).clone();
        let pending = self.submit(first, current, next, self.readback.clone())?;
        let pending_next = self.submit(second, current, next, second_buffer)?;
        self.pending_next = Some(pending_next);
        self.finish(pending, output)
    }

    pub fn finish_prefetched(&mut self, output: impl FnOnce(&[u8])) -> Result<(), String> {
        let pending = self.pending_next.take().ok_or("missing prefetched readback")?;
        self.finish(pending, output)
    }

    pub fn cancel_prefetch(&mut self) {
        if let Some(pending) = self.pending_next.take() {
            // Cancel a pending or completed map and retire its buffer.
            // Submitted commands retain their own references; the next
            // prefetch gets a fresh allocation rather than a racing map.
            pending.buffer.unmap();
            self.readback_next = None;
        }
    }

    fn submit(
        &mut self,
        job: &GpuJob,
        current: &[u8],
        next: &[u8],
        readback: wgpu::Buffer,
    ) -> Result<PendingReadback, String> {
        self.device.push_error_scope(wgpu::ErrorFilter::Validation);
        let mut encoder = self.device.create_command_encoder(&Default::default());
        // Retire old sources before allocating new ones; queue ordering makes
        // reuse safe, including when a second output is submitted in flight.
        let retained = self.sources.split_off(&job.n);
        self.recycled_sources.extend(std::mem::replace(&mut self.sources, retained).into_values());
        self.recycled_sources.truncate(2);
        self.source(job.n, current, job.linear, &mut encoder);
        self.source(job.n + 1, next, job.linear, &mut encoder);
        let (w, h) = (job.grid.0 as u32, job.grid.1 as u32);
        // Cache by the actual contents, not merely the frame pair: SAD masks
        // and coverage fields can change with fractional phase.
        let mut base = self.base_field.take();
        self.field(&mut encoder, &mut base, &job.base, w, h);
        self.base_field = base;
        if let Some(data) = job.ext.as_deref() {
            let mut ext = self.ext_field.take();
            self.field(&mut encoder, &mut ext, data, w, h);
            self.ext_field = ext;
        }
        let mask_data = job.mask.as_deref();
        if !self.mask.as_ref().is_some_and(|m| m.grid == (w, h) && m.values.as_deref() == mask_data) {
            let mut mask = self.mask.take().filter(|m| m.grid == (w, h)).unwrap_or_else(|| MaskCache {
                texture: self.texture(w, h, wgpu::TextureFormat::Rgba8Unorm, false),
                grid: (w, h),
                values: None,
            });
            let stride = w as usize * 4;
            self.upload_rows(&mut encoder, &mask.texture, w, h, w * 4, |row, dst| {
                if let Some(data) = mask_data {
                    dst.copy_from_slice(&data[row * stride..(row + 1) * stride]);
                } else {
                    dst.fill(0);
                }
            });
            match mask_data {
                Some(data) => {
                    let values = mask.values.get_or_insert_with(Vec::new);
                    values.clear();
                    values.extend_from_slice(data);
                }
                None => mask.values = None,
            }
            self.mask = Some(mask);
        }
        let base = &self.base_field.as_ref().unwrap().texture;
        let ext = if job.ext.is_some() {
            &self.ext_field.as_ref().unwrap().texture
        } else {
            base
        };
        let mask = &self.mask.as_ref().unwrap().texture;
        // Every Y/U/V output word is overwritten by the managed shader.
        // Unaligned plane boundaries preserve only the earlier plane's bytes;
        // the first plane starts at zero and the last zeros its trailing lanes.
        // No full-frame GPU clear is needed. Retain the old clear in tests
        // for exact A/B parity, including a reused unaligned output buffer.
        #[cfg(test)]
        if self.force_clear_output { encoder.clear_buffer(&self.output, 0, None); }
        for (plane, p) in job.params.iter().enumerate() {
            let key = [
                p.algorithm,
                p.cubic,
                p.cubic_ref,
                p.has_sad,
                p.linear_luma,
                p.dither,
            ];
            if !self.pipelines.contains_key(&key) {
                let constants = [
                    ("ALGO", p.algorithm as f64),
                    ("CUBIC", (p.cubic != 0) as u8 as f64),
                    ("CUBIC_REF", (p.cubic_ref != 0) as u8 as f64),
                    ("HAS_SAD", (p.has_sad != 0) as u8 as f64),
                    ("LINEAR_LUMA", (p.linear_luma != 0) as u8 as f64),
                    ("DITHER", (p.dither != 0) as u8 as f64),
                ];
                let constants = constants
                    .into_iter()
                    .map(|(k, v)| (k.to_string(), v))
                    .collect();
                let pipeline =
                    self.device
                        .create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
                            label: None,
                            layout: Some(&self.pipeline_layout),
                            module: &self.shader,
                            entry_point: Some("render"),
                            compilation_options: wgpu::PipelineCompilationOptions {
                                constants: &constants,
                                ..Default::default()
                            },
                            cache: self.driver_cache.as_ref().map(|(_, cache)| cache),
                        });
                self.pipelines.insert(key, pipeline);
                self.cache_dirty = true;
            }
            let luma = self.width * self.height;
            let start = [0, luma, luma * 5 / 4][plane];
            let (stride_words, groups_x, groups_y) = dispatch_geometry(start, p.width as u32, p.height as u32);
            let params = &self.uniforms[plane];
            self.queue.write_buffer(params, 0, &params_bytes(p, start, stride_words));
            let source_texture = |n| {
                let source = &self.sources[&n];
                if plane == 0 && job.linear {
                    source.linear.as_ref().expect("linear source prepared")
                } else {
                    &source.packed
                }
            };
            let textures = [source_texture(job.n), source_texture(job.n + 1), base, ext, mask];
            let cached = self.plane_bindings[plane].as_ref().is_some_and(|binding|
                binding.textures.iter().zip(textures.iter()).all(|(old, new)| old == *new));
            if !cached {
                let views = textures.map(|texture| texture.create_view(&Default::default()));
                let group = self.device.create_bind_group(&wgpu::BindGroupDescriptor {
                    label: Some("SVP cached plane bindings"),
                    layout: &self.layout,
                    entries: &[
                        wgpu::BindGroupEntry { binding: 0, resource: params.as_entire_binding() },
                        texture_binding(1, &views[0]),
                        texture_binding(2, &views[1]),
                        texture_binding(3, &views[2]),
                        texture_binding(4, &views[3]),
                        texture_binding(5, &views[4]),
                        wgpu::BindGroupEntry { binding: 6, resource: self.output.as_entire_binding() },
                    ],
                });
                self.plane_bindings[plane] = Some(PlaneBinding {
                    textures: textures.map(|texture| (*texture).clone()),
                    group,
                });
            }
            let group = &self.plane_bindings[plane].as_ref().unwrap().group;
            {
                let mut pass = encoder.begin_compute_pass(&Default::default());
                pass.set_pipeline(&self.pipelines[&key]);
                pass.set_bind_group(0, group, &[]);
                pass.dispatch_workgroups(
                    groups_x,
                    groups_y,
                    1,
                );
            }
        }
        encoder.copy_buffer_to_buffer(&self.output, 0, &readback, 0, self.bytes);
        self.queue.submit([encoder.finish()]);
        self.recycle_uploads();
        // Validation scope belongs to this submission. Resolve it before
        // opening a second scope; no wait for the GPU readback is needed here.
        if let Some(e) = pollster::block_on(self.device.pop_error_scope()) {
            return Err(e.to_string());
        }
        let (tx, rx) = mpsc::sync_channel(1);
        readback.slice(..).map_async(wgpu::MapMode::Read, move |r| {
            let _ = tx.send(r);
        });
        Ok(PendingReadback {
            buffer: readback,
            result: rx,
            deadline: std::time::Instant::now() + Duration::from_secs(3),
        })
    }

    fn finish(&mut self, pending: PendingReadback, output: impl FnOnce(&[u8])) -> Result<(), String> {
        // Poll without an unbounded vkWaitForFences: seek/stop must recover from a lost GPU.
        let mapped = loop {
            self.device.poll(wgpu::Maintain::Poll);
            match pending.result.try_recv() {
                Ok(result) => break result.map_err(|e| e.to_string()),
                Err(mpsc::TryRecvError::Disconnected) => break Err("GPU map disconnected".into()),
                Err(_) if std::time::Instant::now() >= pending.deadline => {
                    break Err("GPU compute timeout".into());
                }
                Err(_) => std::thread::sleep(Duration::from_micros(200)),
            }
        };
        mapped?;
        {
            let mapped = pending.buffer.slice(..).get_mapped_range();
            // The caller can deliver directly to a padded player picture
            // while this readback is mapped; the borrowed slice cannot escape.
            output(&mapped[..self.width as usize * self.height as usize * 3 / 2]);
        }
        pending.buffer.unmap();
        if self.cache_dirty {
            if let Some((key, cache)) = &self.driver_cache {
                self.cache_updated |= remember_cache_data(key, cache);
            }
            self.cache_dirty = false;
        }
        Ok(())
    }
}

// WGSL render uses 8x8 invocations, each writing one packed u32 (four
// pixels). Unaligned planes use a flattened word grid, preserving the bytes
// written by the preceding plane at a shared boundary word.
impl Drop for Gpu {
    fn drop(&mut self) {
        // Save once at session end, not during frame rendering. Do not
        // persist a cache from a failed render/validation scope.
        if self.cache_updated && !self.cache_dirty {
            if let Some((key, _)) = &self.driver_cache {
                let data = WARM_PIPELINE_CACHE.lock().ok().and_then(|warm|
                    warm.as_ref().filter(|(k, _)| k == key).map(|(_, data)| data.clone()));
                if let Some(data) = data { let _ = pipeline_cache::store(key, &data); }
            }
        }
    }
}

fn synthesis_source(compact_fields: bool) -> Result<Cow<'static, str>, String> {
    let source = include_str!("../shaders/smooth.wgsl");
    if !compact_fields { return Ok(Cow::Borrowed(source)); }
    // Keep the managed upstream file byte-identical. Only RAW16 sampling
    // needs a different scale; FLOAT returns early and UNORM8 sets 255.
    // Refuse the variant if a future pinned shader changes this contract.
    const FROM: &str = "var scale = 1.0;";
    if source.matches(FROM).count() != 1
        || !source.contains("if (kind == UNORM8) {\n    scale = 255.0;")
        || !source.contains("if (kind == FLOAT)")
    {
        return Err("unsupported upstream compact-field shader".into());
    }
    Ok(Cow::Owned(source.replacen(FROM, "var scale = 65535.0;", 1)))
}

fn dispatch_geometry(base: u32, width: u32, height: u32) -> (u32, u32, u32) {
    let words_per_row = width.div_ceil(4);
    let rows = if base % 4 == 0 && width % 4 == 0 {
        height
    } else {
        ((base % 4 + width * height).div_ceil(4)).div_ceil(words_per_row)
    };
    (words_per_row, words_per_row.div_ceil(8), rows.div_ceil(8))
}

fn texture_entry(binding: u32) -> wgpu::BindGroupLayoutEntry {
    wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::COMPUTE,
        ty: wgpu::BindingType::Texture {
            sample_type: wgpu::TextureSampleType::Float { filterable: false },
            view_dimension: wgpu::TextureViewDimension::D2,
            multisampled: false,
        },
        count: None,
    }
}
fn texture_binding(binding: u32, view: &wgpu::TextureView) -> wgpu::BindGroupEntry<'_> {
    wgpu::BindGroupEntry {
        binding,
        resource: wgpu::BindingResource::TextureView(view),
    }
}
fn params_bytes(p: &GpuParams, base: u32, stride: u32) -> [u8; 96] {
    let mut data = [0u8; 96];
    let ints = [
        p.algorithm, p.width, p.height, p.x_ratio, p.y_ratio, p.pel,
        p.block_w, p.block_h, p.origin_x, p.origin_y, p.phase, p.has_sad,
        p.linear_luma, p.cubic, p.cubic_ref, p.offset_x, p.offset_y,
    ];
    for (dst, v) in data.chunks_exact_mut(4).zip(ints) {
        dst.copy_from_slice(&v.to_le_bytes());
    }
    data[68..72].copy_from_slice(&p.sad_blend.to_le_bytes());
    data[72..76].copy_from_slice(&p.dither.to_le_bytes());
    data[76..80].copy_from_slice(&base.to_le_bytes());
    data[80..84].copy_from_slice(&stride.to_le_bytes());
    data
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn compact_fields_recover_all_u16_values_and_keep_upstream_source() {
        for v in 0..=u16::MAX {
            let normalized = f32::from(v) / 65535.0;
            assert_eq!((normalized * 65535.0).round() as u16, v);
        }
        let original = synthesis_source(false).unwrap();
        let compact = synthesis_source(true).unwrap();
        assert_eq!(compact.replacen("var scale = 65535.0;", "var scale = 1.0;", 1), original);
    }

    #[test]
    fn dispatch_covers_every_word_once() {
        for (w, h) in [(32, 32), (33, 17), (64, 64), (65, 33), (960, 540), (1920, 1080)] {
            for base in [0, 1, 2, 3, 4096] {
                let (stride, gx, gy) = dispatch_geometry(base, w, h);
                let words = (base % 4 + w * h).div_ceil(4);
                let mut covered = vec![0u8; words as usize];
                for y in 0..gy * 8 {
                    for x in 0..gx * 8 {
                        if x >= stride { continue; }
                        let i = y * stride + x;
                        if i < words { covered[i as usize] += 1; }
                    }
                }
                assert!(covered.iter().all(|n| *n == 1), "{base} {w}x{h}");
            }
        }
    }

    #[test]
    #[ignore = "requires hardware Vulkan"]
    fn hd_staged_input_is_bounded_and_rejected_index_can_be_reused() {
        let (w,h) = (1280u32,720u32);
        let mut gpu = Gpu::new(w,h).unwrap();
        let data = vec![40; (w*h*3/2) as usize];
        for index in 0..8 {
            gpu.stage_source(index, &data).unwrap();
        }
        assert_eq!(gpu.sources.len(), 3);
        gpu.discard_source(1);
        assert!(!gpu.sources.contains_key(&1));
        gpu.stage_source(1, &vec![200; data.len()]).unwrap();
        assert_eq!(gpu.sources.len(), 3);
        gpu.clear_sources();
        assert!(gpu.sources.is_empty());
        gpu.stage_source(0, &data).unwrap();
        assert_eq!(gpu.sources.len(), 1);
    }

    // Also runnable as an Android test executable via cargo ndk test --lib --no-run.
    // The original write_texture path SIGSEGVs on the emulator at 2560x1440.
    #[test]
    #[ignore = "requires hardware Vulkan"]
    fn texture_upload_round_trip_at_video_resolutions() {
        for (w, h) in [(128, 72), (1920, 1080), (2560, 1440), (3840, 2160)] {
            for cycle in 0..3 {
                let mut gpu = Gpu::new(w, h).unwrap();
                let data: Vec<u8> = (0..w as usize * h as usize * 3 / 2)
                    .map(|n| ((n * 17 + n / w as usize + cycle * 31) % 251) as u8).collect();
                let mut upload = gpu.device.create_command_encoder(&Default::default());
                gpu.source(0, &data, false, &mut upload);
                gpu.queue.submit([upload.finish()]);
                let pitch = w.div_ceil(wgpu::COPY_BYTES_PER_ROW_ALIGNMENT) * wgpu::COPY_BYTES_PER_ROW_ALIGNMENT;
                let readback = gpu.device.create_buffer(&wgpu::BufferDescriptor {
                    label: Some("SVP upload regression readback"),
                    size: pitch as u64 * (h * 3 / 2) as u64,
                    usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
                    mapped_at_creation: false,
                });
                // The production source texture needs COPY_SRC only for this readback test.
                let mut encoder = gpu.device.create_command_encoder(&Default::default());
                encoder.copy_texture_to_buffer(
                    gpu.sources[&0].packed.as_image_copy(),
                    wgpu::TexelCopyBufferInfo { buffer: &readback, layout: wgpu::TexelCopyBufferLayout {
                        offset: 0, bytes_per_row: Some(pitch), rows_per_image: Some(h * 3 / 2),
                    } },
                    wgpu::Extent3d { width: w, height: h * 3 / 2, depth_or_array_layers: 1 },
                );
                gpu.queue.submit([encoder.finish()]);
                let (tx, rx) = mpsc::sync_channel(1);
                readback.slice(..).map_async(wgpu::MapMode::Read, move |r| { tx.send(r).unwrap(); });
                gpu.device.poll(wgpu::Maintain::Wait);
                rx.recv_timeout(Duration::from_secs(10)).unwrap().unwrap();
                let mapped = readback.slice(..).get_mapped_range();
                for row in 0..h as usize * 3 / 2 {
                    let actual = &mapped[row * pitch as usize..row * pitch as usize + w as usize];
                    if row < h as usize {
                        assert_eq!(actual, &data[row * w as usize..(row + 1) * w as usize]);
                    } else {
                        let chroma_row = row - h as usize;
                        let luma = (w * h) as usize;
                        let half = w as usize / 2;
                        assert_eq!(&actual[..half], &data[luma + chroma_row * half..luma + (chroma_row + 1) * half]);
                        assert_eq!(&actual[half..], &data[luma * 5 / 4 + chroma_row * half..luma * 5 / 4 + (chroma_row + 1) * half]);
                    }
                }
                drop(mapped);
                readback.unmap();
                eprintln!("PASS upload {w}x{h} cycle={cycle}");
            }
        }
    }
}
